def solve(gi):
    H,W=len(gi),len(gi[0])
    cells=[(i,j,gi[i][j]) for i in range(H) for j in range(W) if gi[i][j]]
    best=None
    for dr,dc in [(1,0),(0,1),(1,1),(1,-1)]:
        used=set(); lines=[]
        for c in cells:
            if c[0]==c[1]: continue  # skip duplicates
