            k=0; pos=[c]; 
            while True:
                nxt=(pos[-1][0]+dr,pos[-1][1]+dc,gi[pos[-1][0]][pos[-1][1]])
                if nxt[2] is None: break
                if nxt in cells and next((p for p in cells if p==nxt),None) not in used:
                    pos.append(nxt); k+=1
                else: break
            used |= set(pos)
            lines.append((dr,dc,k,next(iter(pos)),pos))
        cov=sum(l[2] for l in lines)
        if best is None or cov>best[0]: best=cov,lines
    cov,lines=best
    n=len(lines)
    tab={}  # residue -> (color, last_k)
    def fam(p): return p[1]-p[0] if abs(p[1]-p[0])>abs(p[0]) else p[0]
    for dr,dc,k,col,pos in lines:
        key=fam(next(iter(pos)))
        kk=key%n
        # prefer larger absolute line extent / larger k
        existing=tab[kk]
        if existing is None or (k>=existing[2]):
            tab[kk]=(col,k)
    out=[[0]*W for _ in range(H)]
    for dr,dc,k,col,pos in lines:
        for di,dj in [(dr,dc)]:
            pass
        # fill whole family: iterate all positions along the direction
        if dc!=0: 
            base=(next(iter(pos))[0],0)
        else:
            base=(0,0)
        steps=[]
        for p in pos: steps.append((base[0]+p[0]*0, base[1]+p[1]))
    # simpler: fill all cells whose family key maps to a tabulated residue
    for r in range(H):
        for c in range(W):
            key=fam((r,c))
            if key%n in tab:
                col,k=tab[key%n]
                out[r][c]=col
    return out

