def variant_A(gi):
    kinds=['r','c','d','ad']
    best=(None,-1,None)
    for kk in kinds:
        L=lines_of(gi,kk)
        if not L: continue
        offs={k for kind,k,col in L}
        info=(kk,len(L),len(offs),L)
        if info[1]>best[1]: best=info
    kk,n,p_,L=best
    offs={k for kind,k,col in L}
    # p = #distinct offsets? try also #lines
    for p in (len(offs),n):
        idx={}
        for kind,k,col in L:
            r=k%p
            # nearest offset to r (circular)
            cand=[o for o in offs]
            bestd=min(cand,key=lambda o:(abs(o-r)%p))
            if r not in idx or abs(bestd-r)%p < abs(idx[r]-r)%p:
                idx[r]=col
        out=[[None]*len(gi[0]) for _ in range(len(gi))]
        for i in range(len(gi)):
            for j in range(len(gi[0])):
                k=i if kk=='r' else j if kk=='c' else i-j if kk=='d' else i+j
                out[i][j]=idx.get(k%p,None)
        return out,p
    return None,None

