import os,re,json
from collections import defaultdict
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(g):
    H,W=len(g),len(g[0])
    A=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if g[r][c]: A[g[r][c]].append((r,c))
    orders=sorted(A.items(), key=lambda kv: min(p[0]+p[1] for p in kv[1]))
    sums=[min(p[0]+p[1] for p in pts) for _,pts in orders]
    out=[[0]*W for _ in range(H)]
    for idx,(color,pts) in enumerate(orders):
        new=sums[0]+idx
        for r in range(max(0,new-W+1), min(H,new+1)):
            c=new-r
            if 0<=c<W: out[r][c]=color
    return out
